-- ==========================================
-- CineStream SQLite Database Schema & Seed Data
-- Total Tables: 6 (Movie, Episode, User, Profile, WatchlistItem, WatchProgress)
-- ==========================================

-- ------------------------------------------
-- Table: Movie
-- ------------------------------------------
CREATE TABLE "Movie" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "slug" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "type" TEXT NOT NULL DEFAULT 'movie',
    "synopsis" TEXT NOT NULL,
    "releaseYear" INTEGER NOT NULL DEFAULT 2024,
    "duration" TEXT NOT NULL,
    "rating" TEXT NOT NULL DEFAULT '8.5',
    "genres" TEXT NOT NULL,
    "posterUrl" TEXT NOT NULL,
    "backdropUrl" TEXT NOT NULL,
    "trailerUrl" TEXT,
    "videoUrl" TEXT,
    "isFeatured" BOOLEAN NOT NULL DEFAULT false,
    "isTrending" BOOLEAN NOT NULL DEFAULT false,
    "isImax" BOOLEAN NOT NULL DEFAULT false,
    "director" TEXT,
    "cast" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO Movie ("id", "slug", "title", "type", "synopsis", "releaseYear", "duration", "rating", "genres", "posterUrl", "backdropUrl", "trailerUrl", "videoUrl", "isFeatured", "isTrending", "isImax", "director", "cast", "createdAt") VALUES ('cyber-drift-2099', 'cyber-drift-2099', 'Cyber Drift: 2099', 'movie', 'In the rain-slicked metropolis of Neo-Kyoto, a rogue cybernetic pilot discovers a classified neural protocol that threatens to collapse the boundary between human consciousness and artificial mainframe networks.', 2024, '2h 38m', '8.9', 'Sci-Fi,Action,Cyberpunk', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBToLZT48tp0d_5SUdZB4Z63a9W7jI1zTZUPeZNwp_whm3ahsTF3NLRmyKzGQzsSXTExu5z-i9j96muHY6byuRvPw7ECsEjfEQSppvRvuLUATcxi_fpOO05_XekZXzCfE-WmQKtbZIjUCMHqtuJQnIaVM-mwimED4FfNuot33f8f2ES564FTnGr2mDUtVVpfvJsQ3Hl-u2YDcH0XOrbvh6uhR96XbAEYj2viLM_knMBjN1csMxnXsEN', '/images/backdrops/cyber_drift_2099.jpg', NULL, 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/TearsOfSteel.mp4', 1, 1, 1, 'Kenji Takahashi', '[{"name":"Marcus Vance","role":"Dr. Marcus Vance","avatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150"},{"name":"Elena Rostova","role":"Commander Kaelen","avatar":"https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150"},{"name":"Kenji Takahashi","role":"The Oracle / Lead","avatar":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150"}]', 1789981608692);
INSERT INTO Movie ("id", "slug", "title", "type", "synopsis", "releaseYear", "duration", "rating", "genres", "posterUrl", "backdropUrl", "trailerUrl", "videoUrl", "isFeatured", "isTrending", "isImax", "director", "cast", "createdAt") VALUES ('dune-part-two', 'dune-part-two', 'Dune: Part Two', 'movie', 'Paul Atreides unites with Chani and the Fremen while seeking revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the universe, he endeavors to prevent a terrible future only he can foresee.', 2024, '2h 46m', '8.8', 'Sci-Fi,Adventure,Action', 'https://images.unsplash.com/photo-1534447677768-be436bb09401?w=600&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=1400&auto=format&fit=crop&q=80', NULL, 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4', 1, 1, 1, 'Denis Villeneuve', '[{"name":"Timothée Chalamet","role":"Paul Atreides","avatar":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=150"},{"name":"Zendaya","role":"Chani","avatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150"},{"name":"Rebecca Ferguson","role":"Lady Jessica","avatar":"https://images.unsplash.com/photo-1517841905240-472988babdf9?w=150"}]', 1789981608697);
INSERT INTO Movie ("id", "slug", "title", "type", "synopsis", "releaseYear", "duration", "rating", "genres", "posterUrl", "backdropUrl", "trailerUrl", "videoUrl", "isFeatured", "isTrending", "isImax", "director", "cast", "createdAt") VALUES ('oppenheimer', 'oppenheimer', 'Oppenheimer', 'movie', 'The story of American scientist J. Robert Oppenheimer and his role in the development of the atomic bomb during the Manhattan Project.', 2023, '3h 00m', '8.9', 'Biography,Drama,History', 'https://images.unsplash.com/photo-1440404653325-ab127d49abc1?w=600&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=1400&auto=format&fit=crop&q=80', NULL, 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', 0, 1, 1, 'Christopher Nolan', '[{"name":"Cillian Murphy","role":"J. Robert Oppenheimer","avatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150"},{"name":"Emily Blunt","role":"Katherine Oppenheimer","avatar":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150"},{"name":"Matt Damon","role":"Leslie Groves","avatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150"}]', 1789981608704);
INSERT INTO Movie ("id", "slug", "title", "type", "synopsis", "releaseYear", "duration", "rating", "genres", "posterUrl", "backdropUrl", "trailerUrl", "videoUrl", "isFeatured", "isTrending", "isImax", "director", "cast", "createdAt") VALUES ('neural-drift-reckoning', 'neural-drift-reckoning', 'Neural Drift: Reckoning', 'series', 'Following the collapse of the central oceanic subnet, Detective Vance and neural operative Elena uncover a syndicate manipulating humanity''s synthetic memories to forge a synthetic digital god.', 2024, '4 Seasons', '9.4', 'Sci-Fi,Crime,Action,Thriller', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAEjIPlBwnrgP6dGCwaj2rc04L8gxxVKud6vIAnM1OZkYBt-Q-ZVELOZxoDaSwJeuWVPBU6T0FaAk8qvZzvPhsDW1e9XKPXotUF5NUWYUeVS1w8TQYKOcWI4qi4tqZyzdQmZ3ZMIbdR0kw74F0dEMDGzBjp2GFgBjDOMM9oCpsBNPJ8_fO2doSM6t7U-WrXecMONLn05AFOkCAccpuA9i7xycGjs9JdX5dOCRa2vD202Y9BH79LBibL', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?w=1400&auto=format&fit=crop&q=80', NULL, 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4', 1, 1, 1, 'Kenji Takahashi & David Fincher', '[{"name":"Marcus Vance","role":"Detective Marcus Vance","avatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150"},{"name":"Elena Rostova","role":"Elena Rostova","avatar":"https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150"}]', 1789981608710);
INSERT INTO Movie ("id", "slug", "title", "type", "synopsis", "releaseYear", "duration", "rating", "genres", "posterUrl", "backdropUrl", "trailerUrl", "videoUrl", "isFeatured", "isTrending", "isImax", "director", "cast", "createdAt") VALUES ('blade-runner-2049', 'blade-runner-2049', 'Blade Runner 2049', 'movie', 'Young Blade Runner K''s discovery of a long-buried secret leads him to track down former Blade Runner Rick Deckard, who''s been missing for thirty years.', 2017, '2h 44m', '8.0', 'Sci-Fi,Mystery,Drama', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=600&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1514565131-fce0801e5785?w=1400&auto=format&fit=crop&q=80', NULL, 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/TearsOfSteel.mp4', 0, 0, 1, 'Denis Villeneuve', '[{"name":"Ryan Gosling","role":"Officer K","avatar":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=150"},{"name":"Harrison Ford","role":"Rick Deckard","avatar":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150"}]', 1789981608727);
INSERT INTO Movie ("id", "slug", "title", "type", "synopsis", "releaseYear", "duration", "rating", "genres", "posterUrl", "backdropUrl", "trailerUrl", "videoUrl", "isFeatured", "isTrending", "isImax", "director", "cast", "createdAt") VALUES ('interstellar', 'interstellar', 'Interstellar', 'movie', 'When Earth becomes uninhabitable in the future, a farmer and ex-NASA pilot, Joseph Cooper, is tasked to pilot a spacecraft, along with a team of researchers, to find a new planet for humans.', 2014, '2h 49m', '8.7', 'Sci-Fi,Adventure,Drama', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=600&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?w=1400&auto=format&fit=crop&q=80', NULL, 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', 0, 1, 1, 'Christopher Nolan', '[{"name":"Matthew McConaughey","role":"Cooper","avatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150"},{"name":"Anne Hathaway","role":"Brand","avatar":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150"}]', 1789981608731);
INSERT INTO Movie ("id", "slug", "title", "type", "synopsis", "releaseYear", "duration", "rating", "genres", "posterUrl", "backdropUrl", "trailerUrl", "videoUrl", "isFeatured", "isTrending", "isImax", "director", "cast", "createdAt") VALUES ('shogun', 'shogun', 'Shōgun', 'series', 'When a mysterious European ship is found marooned in a nearby fishing village, Lord Yoshii Toranaga discovers secrets that could tip the scales of power and devastate his formidable enemies.', 2024, '1 Seasons', '9.1', 'Action,Adventure,Drama,History', 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?w=600&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?w=1400&auto=format&fit=crop&q=80', NULL, 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4', 0, 1, 0, 'Rachel Kondo & Justin Marks', '[{"name":"Hiroyuki Sanada","role":"Lord Yoshii Toranaga","avatar":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150"},{"name":"Cosmo Jarvis","role":"John Blackthorne","avatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150"},{"name":"Anna Sawai","role":"Toda Mariko","avatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150"}]', 1789981608735);
